<?php

namespace App\Policies;

use App\Models\Quotation;
use App\Models\User;

class QuotationPolicy
{
    public function view(User $user, Quotation $quotation): bool
    {
        if ($user->id === $quotation->user_id || $user->hasRole('super-admin')) {
            return true;
        }

        // Admin: only their own quotations plus everything generated by
        // 'user'-role accounts — not other admins'/super-admin's.
        return $user->hasRole('admin') && ($quotation->user?->hasRole('user') ?? false);
    }

    public function create(User $user): bool
    {
        return true;
    }

    public function delete(User $user, Quotation $quotation): bool
    {
        return $user->id === $quotation->user_id || $user->hasRole('admin');
    }
}
